int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < bb.limit()) {
        int octet = bb.get(i);
        if (octet >= 0) {
            sb.append((char) octet);
            i++;
        } else if ((octet >> 5) == -2) {
            sb.append((char) ((octet & 0x1F) << 6 | (bb.get(i + 1) & 0x3F)));
            i += 2;
        } else if ((octet >> 4) == -2) {
            sb.append((char) ((octet & 0x0F) << 12 | (bb.get(i + 1) & 0x3F) << 6 | (bb.get(i + 2) & 0x3F)));
            i += 3;
        } else {
            throw new IllegalStateException("Invalid octet at " + i);
        }
    }
    return i;
}
