    public void add(Object value) {
        Node newNode = new Node(value);
        if (size == 0) {
            head = newNode;
            tail = newNode;
        } else {
            tail.setNext(newNode);
            tail = newNode;
        }
        size++;
    }

    public Object remove() {
        if (size == 0) {
            throw new EmptyQueueException();
        }
        Object value = head.getValue();
        head = head.getNext();
        size--;
        return value;
    }

    public boolean isEmpty() {
        return size == 0;
    }

