public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Open the file for reading
    BufferedReader reader = new BufferedReader(new FileReader(file));

    // Initialize the output list
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    // Parse the file line by line
    String line;
    while ((line = reader.readLine()) != null) {
        // Skip empty lines and comments
        if (line.trim().isEmpty() || line.startsWith("#")) {
            continue;
        }

        // Split the line into tokens using whitespace as the delimiter
        String[] tokens = line.split("\\s+");

        // Check if the line has the expected number of tokens
        if (tokens.length != 5) {
            throw new IllegalArgumentException("Invalid data format in file: " + file.getName());
        }

        // Parse the tokens into a ThreadProfile object
        ThreadProfile profile = new ThreadProfile();
        profile.setThreadId(Integer.parseInt(tokens[0]));
        profile.setName(tokens[1]);
        profile.setType(ThreadType.valueOf(tokens[2]));
        profile.setExecutionTime(Long.parseLong(tokens[3]));
        profile.setWaitTime(Long.parseLong(tokens[4]));

        // Check if any of the time ranges match the execution time
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (profile.getExecutionTime() >= timeRange.getStartTime() &&
                    profile.getExecutionTime() <= timeRange.getEndTime()) {
                // Add the profile to the output list if it matches the time range
                snapshots.add(profile);
                break;
            }
        }
    }

    // Close the file
    reader.close();

    // Return the output list
    return snapshots;
}
